import { useEffect, useState } from "react";
import { Link } from "react-router-dom";

export default function CustomerList() {
  const [customers, setCustomers] = useState([]);
  const [city, setCity] = useState("");
  const [stateFilter, setStateFilter] = useState("");
  const [pin, setPin] = useState("");

  const fetchCustomers = async (filters = {}) => {
    let query = "";
    if (filters.city) query += `city=${filters.city}&`;
    if (filters.state) query += `state=${filters.state}&`;
    if (filters.pinCode) query += `pinCode=${filters.pinCode}&`;

    const res = await fetch(
      `http://localhost:5000/customers?${query}`
    );
    const data = await res.json();
    setCustomers(data);
  };

  useEffect(() => {
    fetchCustomers();
  }, []);

  const handleSearch = () => {
    fetchCustomers({ city, state: stateFilter, pinCode: pin });
  };

  const handleClear = () => {
    setCity(""); setStateFilter(""); setPin("");
    fetchCustomers();
  };

  const handleDelete = async (id) => {
    if (window.confirm("Delete this customer?")) {
      await fetch(`http://localhost:5000/customers/${id}`, {
        method: "DELETE",
      });
      fetchCustomers();
    }
  };

  return (
    <div style={{ padding: "0 20px" }}>
      <div style={{ marginBottom: "20px" }}>
        <Link to="/create">Add Customer</Link>
      </div>

      <div style={{ marginBottom: "10px" }}>
        <input
          placeholder="City"
          value={city}
          onChange={(e) => setCity(e.target.value)}
        />
        <input
          placeholder="State"
          value={stateFilter}
          onChange={(e) => setStateFilter(e.target.value)}
        />
        <input
          placeholder="Pin Code"
          value={pin}
          onChange={(e) => setPin(e.target.value)}
        />
        <button onClick={handleSearch}>Search</button>
        <button onClick={handleClear}>Clear</button>
      </div>

      {customers.length === 0 ? (
        <p>No customers found</p>
      ) : (
        customers.map((c) => (
          <div
            key={c.id}
            style={{
              border: "1px solid #ccc",
              padding: "10px",
              marginBottom: "10px",
            }}
          >
            <Link to={`/customer/${c.id}`}>
              {c.firstName} {c.lastName}
            </Link>
            <button
              onClick={() => handleDelete(c.id)}
              style={{ marginLeft: "10px" }}
            >
              Delete
            </button>
          </div>
        ))
      )}
    </div>
  );
}
